(function(){'use strict';
if(!window.DesktopApp?.marketScanner||!window.PriceBook)return;
const api=window.DesktopApp.marketScanner,book=window.PriceBook,original=book.resolve.bind(book);let rows=[];
book.resolve=function(server,id,city,q,action,quote={},timestamp){const saved=book.get(server,id,city,q,action);if(saved?.source==='manual')return original(server,id,city,q,action,quote,timestamp);const row=rows.find(r=>r.server===server&&r.item===id&&r.city===city&&r.quality===Number(q)),side=action==='bid'?'bid':'ask',time=row?.[side+'Time'];if(row?.[side]>0&&Date.now()-time<7200000&&time<=Date.now()+60000)return {...quote,price:row[side],age:Math.max(0,(Date.now()-time)/3600000),timestamp:new Date(time).toISOString(),reason:'',sourceLabel:'Считано с рынка · '+new Date(time).toLocaleTimeString('ru-RU'),fromScanner:true};return original(server,id,city,q,action,quote,timestamp);};
const panel=document.createElement('dialog');panel.className='market-scanner';panel.style.cssText='padding:24px;border:1px solid #667368;border-radius:8px;max-width:650px;background:#f8efd8;color:#332d20';panel.innerHTML='<h3>Сканирование рынка</h3><button type="button" data-close>Закрыть</button><p>Просматривайте товары в игре — полученные цены поступят в расчёты. Выберите сервер игры перед включением. Цены действуют 2 часа, ручные цены сохраняют приоритет.</p><label>Сервер игры <select><option value="europe">Европа</option><option value="west">Америка</option><option value="east">Азия</option></select></label> <button type="button" data-select>Выбрать клиент AODP</button> <button type="button" data-toggle>Включить сканер рынка</button><p role="status"></p><p>Нужен официальный albiondata-client и Npcap. Запускается отдельная копия клиента с передачей цен только в Albion Lab. Закройте другие копии клиента AODP перед включением. Сервер сканирования задаётся здесь независимо от сервера открытого расчёта.</p>';
document.body.append(panel);panel.querySelector('[data-close]').onclick=()=>panel.close();const opener=document.createElement('button');opener.type='button';opener.className='button';opener.textContent='Сканер рынка';opener.onclick=()=>{panel.showModal();};document.querySelector('.header-actions')?.append(opener);const status=panel.querySelector('[role=status]'),toggle=panel.querySelector('[data-toggle]'),select=panel.querySelector('select');let running=false;
function paint(state){rows=state.quotes||[];running=state.running;select.disabled=running;panel.querySelector('[data-select]').disabled=running;toggle.textContent=running?'Выключить сканер рынка':'Включить сканер рынка';status.textContent=(state.configured?'Клиент выбран. ':'Выберите официальный клиент AODP. ')+(state.message||'')+' · Сохранено ордеров: '+state.orders;document.dispatchEvent(new Event('pricebookchange'));}
async function action(name,arg){toggle.disabled=true;try{paint(await api.action(name,arg));}catch(e){status.textContent=e.message;}finally{toggle.disabled=false;}}
panel.querySelector('[data-select]').onclick=()=>action('select');toggle.onclick=()=>action(running?'stop':'start',select.value);api.onChanged(paint);action('state');setInterval(()=>api.action('state').then(paint).catch(()=>{}),60000);
})();
